							return EMPTY;
						}),
						// Handle component lifecycle to avoid memory leaks
						untilDestroyed(this)
					);
			}),
			// Handle component lifecycle to avoid memory leaks
			untilDestroyed(this)
		);
	}

	ngOnDestroy(): void {}
}

